<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getSelectContext, getSelectItemContext } from './select-context.svelte.js'; export interface Props extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'> { children?: Snippet; keepMounted?: boolean; ref?: HTMLSpanElement | null; } let { children, keepMounted = false, ref = $bindable(null), ...rest }: Props = $props(); const select = getSelectContext(); const item = getSelectItemContext(); let selected = $derived(select.value === item.value);</script>
{#if keepMounted || selected}<span bind:this={ref} {...rest} hidden={!selected} aria-hidden="true" data-selected={selected ? '' : undefined}>{@render children?.()}</span>{/if}
